// The shape, without Playwright: one exported constant, used in two roles.
const WRONG_CREDENTIALS = "Login and/or password are wrong.";

const bannerTextFromPage = "Login and/or password are wrong.";
console.log("page class compares:", bannerTextFromPage === WRONG_CREDENTIALS);
console.log("a test can import the same string and assert on it exactly");

// Typing it twice is how the two copies drift apart:
const retypedByHand = "Login and/or Password are wrong.";
console.log("retyped by hand matches?", retypedByHand === WRONG_CREDENTIALS);

import { writeProjectFile } from "../_shared/deno-helpers.ts";

// Note assertRefused() - and the exported constant from day2_1.

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week6/generated/zero/LoginPage.ts", `// Week 6, Day 2 — the Zero Bank sign-in screen.
//
// Note assertRefused() below. Week 5 Day 3 gave the rule "no expect() in a page
// object", and this looks like a violation. It is the documented exception:
// the message is INVARIANT — the server returns the same sentence for every wrong
// credential — so it belongs to the page, not to any one test. See day2_2.
import { expect, type Locator, type Page } from "@playwright/test";
import { BasePage } from "./BasePage";

/** The exact banner text, verified live. */
export const WRONG_CREDENTIALS = "Login and/or password are wrong.";

export class LoginPage extends BasePage {
  readonly userName: Locator;
  readonly password: Locator;
  readonly submitButton: Locator;
  readonly rememberMe: Locator;
  readonly errorBanner: Locator;

  constructor(page: Page) {
    super(page);
    this.userName = page.locator("#user_login");
    this.password = page.locator("#user_password");
    this.submitButton = page.locator("input[type='submit']");
    this.rememberMe = page.locator("#user_remember_me");
    this.errorBanner = page.locator(".alert-error");
  }

  async visit(): Promise<void> {
    await this.goto("/login.html");
  }

  /**
   * Fill and submit together, because this form has exactly one button — there is
   * no second thing a person could do after typing. Contrast FeedbackPage, which
   * splits them precisely because it has two.
   */
  async login(user: string, pass: string): Promise<void> {
    await this.userName.fill(user);
    await this.password.fill(pass);
    await this.submitButton.click();
  }

  /** Invariant, so it lives here. A test still chooses whether to call it. */
  async assertRefused(): Promise<void> {
    await expect(this.errorBanner).toContainText(WRONG_CREDENTIALS);
  }

  /**
   * A visual check, owned by the page. The error banner's LOOK - red, positioned
   * above the form - is a property of this screen, not of any one test, so the
   * baseline belongs next to the class that knows the banner exists.
   *
   * Needs day2-visual.config.ts: the first run has no baseline and fails by design.
   */
  async snapshotErrorBanner(): Promise<void> {
    await expect(this.errorBanner).toHaveScreenshot("zero-login-error.png");
  }
}
`);

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week6/generated/day2-rules.spec.ts", `// Week 6, Day 2 — what belongs in a page object, and what never does.
//
// Written by a cell in week6/day2_2.ipynb. Run it yourself:
//   npx playwright test week6/generated/day2-rules.spec.ts
import { test, expect } from "@playwright/test";
import { LoginPage, WRONG_CREDENTIALS } from "./zero/LoginPage";
import { FeedbackPage } from "./zero/FeedbackPage";
import { HomePage } from "./zero/HomePage";

test.describe("Assertions a page object is allowed to own", () => {
  test("Step 1 — an invariant message, asserted by the page class", async ({ page }) => {
    const loginPage = new LoginPage(page);

    await loginPage.visit();
    await loginPage.login("wrong", "wrong");

    // One call. The sentence lives in LoginPage, because the server returns the
    // same one for every bad credential — it is a fact about the page.
    await loginPage.assertRefused();
  });

  test("Step 2 — the same invariant, from different wrong inputs", async ({ page }) => {
    const loginPage = new LoginPage(page);

    for (const [user, pass] of [["a", "b"], ["", ""], ["username", "nope"]]) {
      await loginPage.visit();
      await loginPage.login(user, pass);
      await loginPage.assertRefused();
    }

    // Three different inputs, one message. That is what "invariant" means, and it
    // is the test that proves the assertion belonged in the class.
    await expect(loginPage.errorBanner).toHaveText(WRONG_CREDENTIALS);
  });

  test("Step 3 — the documented credentials are refused too", async ({ page }) => {
    const loginPage = new LoginPage(page);

    await loginPage.visit();
    await loginPage.login("username", "password");

    // The transcript signs in with these. Over HTTP the server refuses them, and
    // its HTTPS port is unreachable from a modern browser. So this app's
    // authenticated pages cannot be automated — see day2_2 for the diagnosis.
    await expect(page).toHaveURL(/login_error=true/);
    await loginPage.assertRefused();
  });
});

test.describe("Fill and submit: together or separate?", () => {
  test("Step 4 — separate, because the screen offers two buttons", async ({ page }) => {
    const feedbackPage = new FeedbackPage(page);

    await feedbackPage.visit();
    await feedbackPage.fillForm("Leela", "leela@example.com", "Subject", "My awesome message");

    // Same fill, then one of two choices. Had fillForm() ended with a click, this
    // test could not exist.
    await feedbackPage.resetForm();
    await feedbackPage.assertReset();
  });

  test("Step 5 — the other choice, from the identical fill", async ({ page }) => {
    const feedbackPage = new FeedbackPage(page);

    await feedbackPage.visit();
    await feedbackPage.fillForm("Leela", "leela@example.com", "Subject", "My awesome message");
    await feedbackPage.submitForm();

    await feedbackPage.assertSent();
  });

  test("Step 6 — text belongs to the test, visibility to the page", async ({ page }) => {
    const feedbackPage = new FeedbackPage(page);

    await feedbackPage.visit();
    await feedbackPage.fillForm("Leela", "leela@example.com", "Subject", "Message");
    await feedbackPage.submitForm();

    // assertSent() only checks the heading is there, because the body is
    // personalised with whatever name the test sent. The test knows the name, so
    // the test owns this assertion.
    await feedbackPage.assertSent();
    await expect(page.locator("body")).toContainText("Thank you for your comments, Leela.");
  });
});

test.describe("The anti-pattern", () => {
  test("Step 7 — a locator declared in the test defeats the whole pattern", async ({ page }) => {
    const homePage = new HomePage(page);
    await homePage.visit();

    // WRONG, deliberately. It passes — that is what makes it dangerous. When the
    // id changes, this line breaks and no page class mentions it, so the search
    // for "where is that selector" starts in the test files.
    const searchBoxDeclaredHere = page.locator("#searchTerm");
    await searchBoxDeclaredHere.fill("bank");

    // RIGHT: the same control, reached through the class that owns it.
    await expect(homePage.searchBox).toHaveValue("bank");
  });
});
`);

// Expected: 7 passed.
await runSpec("week6/generated/day2-rules.spec.ts");

// Prove it rather than believe the table. Two attempts, two different failures.
import { chromium } from "npm:playwright";

const diagBrowser = await chromium.launch();
const diagPage = await diagBrowser.newPage({ ignoreHTTPSErrors: true });

// 1. HTTPS, with the flag people reach for first.
try {
  await diagPage.goto("https://zero.webappsecurity.com/login.html", { timeout: 15000 });
  console.log("HTTPS: loaded (unexpected)");
} catch (e) {
  console.log("HTTPS:", (e as Error).message.slice(0, 74));
}

// 2. HTTP, with the credentials the session signs in with.
// A FRESH page: the failed navigation above leaves the old one on an error page,
// and the next goto would race it.
const httpPage = await diagBrowser.newPage();
await httpPage.goto("http://zero.webappsecurity.com/login.html");
await httpPage.locator("#user_login").fill("username");
await httpPage.locator("#user_password").fill("password");
await httpPage.locator("input[type='submit']").click();
await httpPage.waitForLoadState("load");
console.log("HTTP login ->", httpPage.url().split("/").pop());
console.log("banner     :", (await httpPage.locator(".alert-error").innerText()).trim());

await diagBrowser.close();

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week6/generated/day2-journey.spec.ts", `// Week 6, Day 2 — a journey across several page objects.
//
// Two things to notice. First: the banking classes are IMPORTED FROM WEEK 5, not
// rewritten. A page object library is cumulative; that is most of its value.
// Second: everything that merely gets us to the screen under test lives in
// beforeEach, so each test body is only the thing it actually checks.
//
// Written by a cell in week6/day2_2.ipynb. Run it yourself:
//   npx playwright test week6/generated/day2-journey.spec.ts
import { test, expect } from "@playwright/test";
import { LoginPage as BankLoginPage } from "../../week5/generated/pages/LoginPage";
import { DashboardPage } from "../../week5/generated/pages/DashboardPage";
import { NavBar } from "./components/NavBar";
import { HomePage } from "./zero/HomePage";
import { FeedbackPage } from "./zero/FeedbackPage";

test.describe("Banking journey — four objects, one flow", () => {
  let bankLoginPage: BankLoginPage;
  let dashboardPage: DashboardPage;
  let navBar: NavBar;

  test.beforeEach(async ({ page }) => {
    bankLoginPage = new BankLoginPage(page);
    dashboardPage = new DashboardPage(page);
    navBar = new NavBar(page);

    // The precondition, once. Signing in is not what any test below is testing.
    await bankLoginPage.goto("/");
    await bankLoginPage.signIn();
  });

  test("Step 1 — the precondition landed us somewhere real", async () => {
    await expect(dashboardPage.userName).toBeVisible();
    await expect(navBar.tiles).toHaveCount(12);
  });

  test("Step 2 — navigate, then assert on the destination", async ({ page }) => {
    await navBar.clickOnTab("Pay Bills");
    await expect(page).toHaveURL(/paymentDashboard/);
  });

  test("Step 3 — a different destination, same three lines", async ({ page }) => {
    await navBar.clickOnTab("Add Payee");
    await expect(page).toHaveURL(/transferDashboard/);
    expect(dashboardPage.section()).toBe("transferDashboard");
  });

  test("Step 4 — and back out again", async ({ page }) => {
    await navBar.clickOnTab("Transaction History");
    await expect(page).toHaveURL(/accountDashboard/);

    await dashboardPage.goto("/dashboard");
    await dashboardPage.signOut();
    await expect(page).toHaveURL(/login/);
  });
});

test.describe("Zero Bank journey — two objects, one flow", () => {
  let homePage: HomePage;
  let feedbackPage: FeedbackPage;

  test.beforeEach(async ({ page }) => {
    homePage = new HomePage(page);
    feedbackPage = new FeedbackPage(page);

    // Reaching feedback THROUGH the home page, rather than jumping straight to
    // its URL — because that is the route a person takes.
    await homePage.visit();
    await homePage.clickOnFeedbackLink();
  });

  test("Step 5 — the form is reachable from the landing page", async () => {
    await expect(feedbackPage.nameInput).toBeVisible();
    await expect(feedbackPage.clearButton).toBeVisible();
  });

  test("Step 6 — clearing, from that same starting point", async () => {
    await feedbackPage.fillForm("Leela", "leela@example.com", "Subject", "Message");
    await feedbackPage.resetForm();
    await feedbackPage.assertReset();
  });

  test("Step 7 — sending, from that same starting point", async () => {
    await feedbackPage.fillForm("Leela", "leela@example.com", "Subject", "Message");
    await feedbackPage.submitForm();
    await feedbackPage.assertSent();
  });
});
`);

// Expected: 7 passed. Two apps, two describe blocks, two preconditions.
await runSpec("week6/generated/day2-journey.spec.ts");

## `beforeEach` and `page` - the constraint from week 3

The classes are constructed **inside** `beforeEach`, not at module level:

```ts
let bankLoginPage: BankLoginPage;

test.beforeEach(async ({ page }) => {
  bankLoginPage = new BankLoginPage(page);   // needs the per-test page
  ...
});
```

Every test gets a fresh `page` ([week3/day2_2](/learn/w3/d2/p2)), so a page object built
once at module level would hold a stale one. Declare outside, construct inside.

## A visual check the page owns

The error banner's **look** - red, above the form - is a property of the login screen, not of any
one test. So the baseline can live with the class:

```ts
async snapshotErrorBanner(): Promise<void> {
  await expect(this.errorBanner).toHaveScreenshot("zero-login-error.png");
}
```

Same test as [week4/day5_2](/learn/w4/d5/p2), now behind a method name. It needs its own
config, because a first run has no baseline and fails by design.

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week6/generated/day2-visual.config.ts", `// Week 6, Day 2 — its own config, because a visual test cannot pass on first run.
//
// The first run has no baseline: Playwright writes one and reports failure. That is
// correct behaviour, and it would turn a clean checkout red, so this lesson stays
// out of the default suite. Same reasoning as week4/generated/day5-visual.config.ts.
//
//   npx playwright test -c week6/generated/day2-visual.config.ts
import { defineConfig, devices } from "@playwright/test";

export default defineConfig({
  testDir: ".",
  testMatch: ["day2-visual.visualdemo.ts"],
  retries: 0,
  workers: 1,
  reporter: [["list"]],
  use: { ...devices["Desktop Chrome"] },
  expect: {
    // Anti-aliasing differs by a pixel or two between runs; an exact match would
    // fail for reasons that have nothing to do with the app.
    toHaveScreenshot: { maxDiffPixelRatio: 0.02, animations: "disabled" },
  },
});
`);

await writeProjectFile("week6/generated/day2-visual.visualdemo.ts", `// Week 6, Day 2 — a visual assertion living inside a page object.
//
// Named .visualdemo.ts, not .spec.ts, so the root testMatch never collects it.
// Run it with its own config:
//   npx playwright test -c week6/generated/day2-visual.config.ts
import { test, expect } from "@playwright/test";
import { LoginPage } from "./zero/LoginPage";

test.describe("A visual check owned by the page object", () => {
  test("Step 1 — the banner appears before we photograph it", async ({ page }) => {
    const loginPage = new LoginPage(page);
    await loginPage.visit();
    await loginPage.login("wrong", "wrong");

    // Assert it exists first. toHaveScreenshot on a missing element gives you a
    // timeout, which reads like a visual failure and is not one.
    await loginPage.assertRefused();
    await expect(loginPage.errorBanner).toBeVisible();
  });

  test("Step 2 — the snapshot method, called by the test", async ({ page }) => {
    const loginPage = new LoginPage(page);
    await loginPage.visit();
    await loginPage.login("wrong", "wrong");
    await loginPage.assertRefused();

    // One line. The baseline name and the element both live in LoginPage.
    await loginPage.snapshotErrorBanner();
  });
});
`);

// Baseline already committed, so: 2 passed. Delete the -snapshots folder to see the first-run failure.
await runSpec("week6/generated/day2-visual.visualdemo.ts", { extraArgs: ["-c", "week6/generated/day2-visual.config.ts"] });
